  setTimeout(() => kicker.classList.add('is-shown'), 200);

  if (reducedMotion) {
    typeTarget.innerHTML = TITLE.replace(/\n/g, '<br>');
    caret.classList.add('is-hidden');
    subtitle.classList.add('is-shown');
    cta.classList.add('is-shown');
  } else {
    let i = 0;
    setTimeout(() => {
      const tick = setInterval(() => {
