        typeTarget.innerHTML = TITLE.slice(0, i).replace(/\n/g, '<br>');
        if (i >= TITLE.length) {
          clearInterval(tick);
          // blink 6 times (~2.4s) then reveal subtitle & CTA
          let blinkCount = 0;
          const blinkInterval = setInterval(() => {
            blinkCount++;
            if (blinkCount >= 6) {
              clearInterval(blinkInterval);
              caret.classList.add('is-hidden');
              subtitle.classList.add('is-shown');
              cta.classList.add('is-shown');
            }
          }, 400);
        }
      }, 42);
    }, 1400);
  }

  /* ============================================
     HERO POSTCARDS — entrance + hover
