  document.querySelectorAll('.hero-postcard').forEach(card => {
    const r = parseFloat(card.dataset.rotation) || 0;
    card._restRotation = r;
    gsap.set(card, { rotation: r, opacity: 0, scale: 0.85, y: 30 });
