    if (!isTouch) {
      document.querySelectorAll('.hero-postcard').forEach(card => {
        const r = card._restRotation;
        card.addEventListener('mouseenter', () => {
          gsap.to(card, {
            rotation: 0,
            scale: 1.08,
            duration: 0.7,
            ease: 'power3.out',
